GimCorpus.put(431,0,[[1,1,"ופוסל העבודה. א\"א לא מחוור מן הגמרא שיהא חייב מיתה ויפסול עבודה אלא שהוא באזהרה:",1,0],[1,5,"שתה רביעית. א\"א אף זה לא מחוור דפטור קאמרינן אבל מותר לעבוד לא אמרינן אלא שהוא מותר להורות:",1,0],[1,6,"ועדיין לא סר יינו מעליו. א\"א אינו מן הטעם הזה אלא מפני שהקטרת אימורין כל הלילה:",1,0],[1,7,"כל כהן שיודע וכו'. א\"א הלכה כרבי שתקנתו קלקלתו שאין עכשיו שעת עבודה ולמהרה יבנה לא חיישינן ובין מכיר ובין שאינו מכיר מותר לשתות יין דסתמא אמר אביי כמאן שתו כהני האידנא חמרא כרבי:",1,0],[1,7,"עד שיקבע בבית אב שלו. א\"א כמה דבריו חלושים וקלושים וכי כשיבנה בית המקדש לא יהיה שם מצרף ומטהר ומודיע המשמרות הראויות ושבתם ויומם ואי זה שהות יהיה שם לקביעותם:",2,0],[1,10,"אלא בשעת ביאה. א\"א ליתיה להאי כללא שאפילו שלא בשעת ביאה אסור לגדל פרע שהרי חייב להסתפר משלשים יום לשלשים יום כדכתיב ופרע לא ישלחו. (ביאה למקדש פירוש במשמרתם):",1,0],[1,15,"מן המזבח ולפנים. א\"א זה לא מצאתיו אלא כשהוא קרב למזבח שכך שנו בתורת כהנים בבאכם אל אהל מועד [אין לי אלא אוהל מועד מנין לעשות מזבח כאהל מועד] ת\"ל אתה ובניך אתך וגו' וכן יציאה כביאה מאתך מ\"מ מזבח קאמר אבל לפנים מן המזבח מעלות דרבנן הם ואין בהן מלקות ולא מיתה:",1,0],[1,16,"כגון ששתה רביעית יין. א\"א אם לדבריו אין צורך שישתה היין בין האולם למזבח ומה שאמרו בתורת כהנים מנין אף ביציאה לומר שאף אם שתה בחוץ ונכנס להיכל חייב דה\"ק רחמנא בזמן ביאה לא תהא שכרות בהיכל ובמזבח מיתה נמי איכא בשתוי יין:",1,0],[2,5,"בין כהן הדיוט. א\"א תימה גדול הוא זה שלא נאמר אותו פסוק אלא לאותה שעה בשביל שנמשחו בניו ומה שאמרו בתורת כהנים מנין לכהנים שבכל הדורות לכהנים הגדולים שבכל הדורות קאמר שהרי שמן משחת קדש הוא מרבה אותם:",1,0],[2,6,"אע\"פ שאינו יוצא. א\"א וכיון שהוא חייב להתאבל עליו למה אינו יוצא ודאי יוצא ומטמא בעל כרחו:",1,0],[3,9,"או מחוסר כפורים. א\"א זה שבוש דמחוסר כפורים שנכנס למחנה שכינה דהיינו משער נקנור ולפנים יש בו כרת ובתוס' דכלים תניא כל הטמאים שנכנסו לפנים משער ניקנור אפילו הם מחוסרי כפרה הרי אלו חייבין על זדונן כרת ועל שגגתן חטאת:",1,0],[3,13,"או שיגע באדם. א\"א שבוש הוא זה שאין הנזיר מגלח על מגע כלים שנגעו במת ואפילו של חרב וכן אינו חייב על מגען על ביאת מקדש:",1,0],[3,14,"כל הטעון ביאת מים. א\"א דבריו סותרין זה את זה:",1,0],[3,16,"ועל כיבוס בגדיו לוקה ארבעים. א\"א ומאחר שעל כבוס בגדים אין בו כרת המכניס כלי טמא למקדש למה ענוש כרת על כן אני אומר מה שאמר שמואל במסכת עירובין המכניס טמא שרץ למקדש חייב מלקות קאמר ומה שאמר בסוף יראה לי שאינו לוקה אלא על בגדים שהן אב הטומאה והלא טמא שרץ אינו אב הטומאה וחייב סוף דבר צריך לדקדק אחריו:",1,0],[3,18,"וכן טמא שהכניס וכו'. א\"א שמעתין דזבחים קשיא עליה דעולא אמר ריש לקיש טמא שהכניס ידו למקדש לוקה ואמרי' התם עשה שיש בו כרת הוא ואי משום שמעתא דמסכת יומא אדרבה מהתם משמע דאפילו בטבילת מעלות אמרינן ביאה במקצת שמה ביאה דהא בעי טבילה לכהנות (ואפילו פטור מכרת מלקין אותו):",1,0],[4,4,"וחייב מיתה בידי שמים. א\"א כיון שטבול יום שנכנס למקדש בכרת היכי משכחת לה טבול יום ששימש במיתה והא איכא נמי כרת בשביל ביאת מקדש ואיני מוצא אותו אלא בבמה אי נמי שעשה בית יד ארוכה לצינורא והיפך באיברים מבחוץ:",1,0],[4,4,"וחילל ה\"ז פטור. א\"א והא אמרינן במכות עוד טומאתו בו לרבות מחוסר כיפורים ועוד מבהונות של מצורע דאמרינן בזבחים עשה שיש בו כרת הוא וכל שכן בביאת כולו ועוד וטהרה כתיב ביולדת מכלל דעד השתא טמאה היא ואמרינן בזבחים מחוסר כפורים דזב כזב דמי ובתוספתא דזבחים מונה אותו עם אותן שבמיתה:",2,0],[5,11,"בין שאין בהן (כדי) רביעית. א\"א ובקודח מן הכיור שיש בו לקדש ממנו ד' כהנים:",1,0],[7,5,"מי שיצא בשר יתר בעיניו. א\"א לא ידעתי אם עשה זה כנגד חלזון האמור במשנה בצד עיניו ואינו נראה כן שאם היה בו בשר יתר הוא יבלת בעינו האמור למטה במשנה וחלזון הוא שורה אדמימות העוברת בשחור:",1,0],[8,1,"מי שאמצע [קדקדו עולה למעלה]. א\"א דומה שלא בא זה אלא לערבב את העולם שלא תפס דרך הגמרא ופרטיו לא באו דרך הגמרא:",1,0],[8,13,"בשוקים וברגלים עד שלמעלה מן העקב. א\"א המשנה אמרה פיקה יוצא מגודלו והוא פירש למעלה הפיקין והוא מסבב אותה לענין אחר ובלע\"ז קורין אותו גלוטא ובעל הפיקין פירש בגמרא שיש לו כסתות הרבה והם עגבות והשופנר שאין לו כל עיקר והוא אינו מונה אותו ודומה שכל דבר שיש לו עוגל גדול קורא אותו פיקה כמו שאמרו עד פיקה של גרגרת עד שיעגילו ראש כפיקה של ערב ופיקה משרש פקעיות:",1,0],[9,7,"והוציאן לחוץ מותר וכו'. א\"א הפליג כשאמר מותר לזר להדליקן אלא שאם הדליקן כשירות:",1,0],[9,11,"ועבד חייב. א\"א בתוספתא (פי\"ב) דזבחים כהן שעבד טמא טבול יום מחוסר בגדים ושלא רחוץ ידים ורגלים אינו חייב אלא אחת ואפשר דפליגי תנאי באיסור כולל ואיסור בת אחת:",1,0],[9,12,"וכן בעל מום. א\"א שתיהן שבאו עליו בבת אחת זר ששימש בשבת שהביא שתי שערות בשבת בעל מום שחתך אצבעו בסכין טמאה:",1,0]]);
